// String helpers.
export function reverse(s) {
  return [...s].reverse().join('');
}

export function slugify(s) {
  return s
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { reverse, slugify } from '../src/strings.mjs';

test('reverse', () => { assert.equal(reverse('hello'), 'olleh'); });
test('slugify basic', () => { assert.equal(slugify('Hello World'), 'hello-world'); });
test('slugify collapses punctuation', () => { assert.equal(slugify('foo -- bar!'), 'foo-bar'); });
